/**
 * The response schemas are the web's (web codebase standards plan P4.5): `response-schemas.ts` is
 * GENERATED by the web repo's `scripts/sync-response-schemas.mjs`, which writes the web file's hash
 * to `response-schemas.sha256`. A schema edited here by hand fails this test: change the web file
 * and run the script instead.
 */
// The Node built-ins this test needs, with local shapes rather than widening every other file's
// global types (as `lib/api/raw-fetch-guard.test.ts` does).
declare const __dirname: string;
declare function require(id: string): unknown;
const { readFileSync } = require('fs') as { readFileSync: (file: string, encoding: string) => string };
const { join } = require('path') as { join: (...parts: string[]) => string };
const { createHash } = require('crypto') as {
  createHash: (algorithm: string) => { update: (text: string, encoding: string) => { digest: (enc: string) => string } };
};

const MARKER = '// ---- copied from the web below this line ----\n';
const generated = readFileSync(join(__dirname, 'response-schemas.ts'), 'utf8').replace(/\r\n/g, '\n');

describe('response schemas copied from the web', () => {
  it('carry the generated header', () => {
    expect(generated.indexOf(MARKER)).toBeGreaterThan(0);
  });

  it('match their committed hash', () => {
    const webText = generated.slice(generated.indexOf(MARKER) + MARKER.length);
    const hash = createHash('sha256').update(webText, 'utf8').digest('hex');
    expect(readFileSync(join(__dirname, 'response-schemas.sha256'), 'utf8').trim()).toBe(hash);
  });

  it('import nothing from the web, only zod', () => {
    const imports = [...generated.matchAll(/^import .* from '([^']+)';$/gm)].map((m) => m[1]);
    expect(imports).toEqual(['zod']);
  });
});
